const state = { today: null, answers: {}, view: 'today', historyItems: [], historyMonth: null, historySelectedDate: null, reviewMistakes: [], reviewChallenge: null, reviewConjugations: [], reviewShowAll: false, vocabularyWords: [], vocabularyMonth: null, vocabularySelectedDate: null, vocabularyStarredOnly: false, dailyTimer: null, dailySubmitting: false, readingTimer: null, readingTaskId: null, readingDeadline: null, readingAnswers: {}, readingSubmitting: false, writingPoll: null };
const view = document.querySelector('#view');
const statusBox = document.querySelector('#status');
const esc = value => String(value ?? '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));

async function api(path, options = {}) {
  const response = await fetch(path, {headers:{'Content-Type':'application/json'}, ...options});
  const data = await response.json();
  if (!response.ok) throw new Error(data.error?.message || 'Erreur de connexion');
  return data;
}
function setStatus(message='', error=false){statusBox.textContent=message;statusBox.className=`status${error?' error':''}`}
let activeAudio=null,activeAudioUrl=null,activeSpeakButton=null,activeSpeakLabel=null,speechSequence=0;
function stopSpeech(){speechSequence+=1;if(activeAudio)activeAudio.pause();if(activeAudioUrl)URL.revokeObjectURL(activeAudioUrl);if(activeSpeakButton){activeSpeakButton.disabled=false;activeSpeakButton.innerHTML=activeSpeakLabel}activeAudio=null;activeAudioUrl=null;activeSpeakButton=null;activeSpeakLabel=null}
function speechChunks(text,maxLength=500){const sentences=String(text).match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[String(text)],chunks=[];let current='';const pushPiece=piece=>{const candidate=current?`${current} ${piece}`:piece;if(candidate.length<=maxLength){current=candidate;return}if(current)chunks.push(current);current=piece};sentences.forEach(sentence=>{const clean=sentence.trim();if(clean.length<=maxLength)return pushPiece(clean);let piece='';clean.split(/\s+/).forEach(word=>{if(word.length>maxLength){if(piece){pushPiece(piece);piece=''}for(let offset=0;offset<word.length;offset+=maxLength)pushPiece(word.slice(offset,offset+maxLength));return}const candidate=piece?`${piece} ${word}`:word;if(candidate.length<=maxLength){piece=candidate}else{if(piece)pushPiece(piece);piece=word}});if(piece)pushPiece(piece)});if(current)chunks.push(current);return chunks}
async function playSpeechChunk(chunks,index,requestId,button){if(requestId!==speechSequence)return;button.textContent=chunks.length>1?`▶ Lecture ${index+1}/${chunks.length}`:'▶ Lecture';try{const response=await fetch('/api/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:chunks[index]})});if(requestId!==speechSequence)return;if(!response.ok){const payload=await response.json();throw new Error(payload.error?.message||'Voix française indisponible')}const audioBlob=await response.blob();if(requestId!==speechSequence)return;activeAudioUrl=URL.createObjectURL(audioBlob);activeAudio=new Audio(activeAudioUrl);activeAudio.onended=()=>{if(requestId!==speechSequence)return;if(activeAudioUrl)URL.revokeObjectURL(activeAudioUrl);activeAudio=null;activeAudioUrl=null;if(index+1<chunks.length){playSpeechChunk(chunks,index+1,requestId,button)}else{stopSpeech()}};activeAudio.onerror=()=>{if(requestId!==speechSequence)return;stopSpeech();setStatus('Impossible de lire la prononciation.',true)};await activeAudio.play()}catch(error){if(requestId!==speechSequence)return;stopSpeech();setStatus(error.message,true)}}
function speak(text,button){stopSpeech();const requestId=speechSequence,chunks=speechChunks(text);activeSpeakButton=button;activeSpeakLabel=button.innerHTML;button.disabled=true;playSpeechChunk(chunks,0,requestId,button)}
function speakButton(text,label='Écouter'){return `<button class="speak" data-speak="${esc(text)}" aria-label="${esc(label)}">▶ ${esc(label)}</button>`}
function zhHint(text,label='Afficher l’aide en chinois'){return `<details class="zh-hint"><summary>${esc(label)}</summary><p lang="zh">${esc(text)}</p></details>`}
function completedQuestion(q){const prompt=String(q.prompt||''),markers=[...prompt.matchAll(/_{2,}|…+|\.{3,}/g)];if(!markers.length)return prompt;const first=markers[0],last=markers.at(-1),completed=`${prompt.slice(0,first.index)}${q.answer}${prompt.slice(last.index+last[0].length)}`;return completed.replace(/\s*\([A-Za-zÀ-ÿ'’-]+\)/g,'').replace(/\s+([,.!?])/g,'$1').replace(/\s+/g,' ').trim()}
function spokenQuestion(q){return completedQuestion(q)}

async function showToday(){
  setStatus('Préparation de votre séance…');
  try{state.today=await api('/api/today');renderToday();setStatus('');}catch(error){setStatus(error.message,true)}
}
function renderToday(){
  clearInterval(state.dailyTimer);state.dailyTimer=null;
  const s=state.today,done=s.status==='completed',ready=s.status==='ready';
  const answered=done?s.question_count:Math.max(0,(s.current_position||1)-1);
  const sourceLabel=s.content_source?.startsWith('mistral:')?'Contenu Mistral contrôlé':'Contenu hors ligne contrôlé';
  const total=s.question_count||10,minutes=Math.ceil((s.estimated_seconds||500)/60);
  const hero=`<div class="hero"><div><div class="eyebrow">Séance du ${esc(formatDate(s.study_date))}</div><h1>${done?'Séance terminée':ready?'Votre entraînement est prêt':'Question en cours'}</h1><p>${done?`Score : ${s.score}/${total} · Consultez les explications.`:`${total} questions · niveaux B1–C1 · environ ${minutes} minutes · ${sourceLabel}`}</p></div><div class="progress-box"><div class="progress-label"><span>Progression</span><strong>${answered}/${total}</strong></div><div class="progress"><span style="width:${answered/total*100}%"></span></div></div></div>`;
  if(ready){
    view.innerHTML=`${hero}<section class="panel daily-start"><div class="daily-start-clock">≈ ${minutes} min</div><h2>Prêt à commencer ?</h2><p>Le chronomètre de la première question démarre uniquement après votre clic.</p><ul><li><strong>40 secondes</strong> pour chaque choix multiple.</li><li><strong>55 secondes</strong> pour chaque texte à compléter.</li><li>Une question à la fois, sans retour en arrière.</li><li>À zéro, une réponse vide est enregistrée et la question suivante apparaît.</li></ul><p class="daily-start-note">Chaque réponse est sauvegardée immédiatement. Après la dixième, la séance est corrigée automatiquement.</p><button id="daily-start" class="primary">Commencer la séance</button></section>`;
    document.querySelector('#daily-start').addEventListener('click',startDaily);return;
  }
  if(done){
    view.innerHTML=`${hero}${s.questions.map((q,i)=>questionCard(q,i,true)).join('')}<div class="actions"><span class="action-note">Les réponses et explications sont maintenant visibles.</span><button class="secondary" data-view="history">Voir l’historique</button></div>`;
    bindCommon();return;
  }
  const q=s.questions[0],position=s.current_position,draft=readDailyDraft(s.id,q.id);
  view.innerHTML=`${hero}<section class="daily-timing" aria-live="polite"><div><span>Question ${position}/${total}</span><small>${q.kind==='mcq'?'Choix multiple · 40 s':'Texte à compléter · 55 s'}</small></div><strong id="daily-timer">–:––</strong><div class="daily-timebar"><span id="daily-timebar-fill"></span></div></section>${questionCard(q,position-1,false,draft)}<div class="actions daily-actions"><span class="action-note">Validez pour passer à la question suivante.</span><button id="daily-answer" class="primary" ${draft.trim()?'':'disabled'}>${position===total?'Terminer et corriger':'Valider et continuer'}</button></div>`;
  bindCommon();
  view.querySelectorAll('input').forEach(input=>input.addEventListener('input',captureDailyDraft));
  const fill=view.querySelector('.fill-input');if(fill)fill.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.value.trim()){event.preventDefault();submitDailyAnswer(false)}});
  document.querySelector('#daily-answer').addEventListener('click',()=>submitDailyAnswer(false));
  startDailyTimer();
}
function questionCard(q,index,done,draft=''){
  const result=done?(q.is_correct?'correct':'incorrect'):'';
  const value=done?(q.user_answer||''):draft;
  const control=q.kind==='mcq'?q.options.map(option=>`<label class="option"><input type="radio" name="q-${q.id}" value="${esc(option)}" ${value===option?'checked':''} ${done?'disabled':''}><span>${esc(option)}</span></label>`).join(''):`<input class="fill-input" name="q-${q.id}" autocomplete="off" value="${esc(value)}" placeholder="Écrivez votre réponse" ${done?'disabled':''}>`;
  const correctSentence=completedQuestion(q),resultLabel=q.timed_out?'Temps écoulé':q.is_correct?'Correct':'Incorrect',explanation=done?`<div class="explanation"><p class="answer-line ${q.is_correct?'good':'bad'}">${q.is_correct?'✓ Bonne réponse':q.timed_out?'⌛ Temps écoulé':'✕ À revoir'} · Réponse : ${esc(q.answer)}</p><p><strong>Votre réponse :</strong> ${esc(q.user_answer||'Non répondu')}</p><p lang="fr">${esc(q.explanation_fr)}</p>${zhHint(q.explanation_zh)}<p class="example answer-example"><strong>Exemple à retenir :</strong> ${esc(correctSentence)} ${speakButton(correctSentence,'Écouter la phrase correcte')}</p>${q.kind==='mcq'?`<ul class="option-notes">${q.options.map(option=>`<li><strong>${esc(option)}</strong> — ${esc(q.option_explanations[option])}</li>`).join('')}</ul>`:''}</div>`:'';
  return `<article class="question-card ${result}"><div class="q-meta"><span>Question ${index+1} · ${q.kind==='mcq'?'Choix multiple':'Texte à compléter'}</span>${done?`<span class="q-result">${resultLabel}</span>`:''}</div><div class="prompt" lang="fr">${esc(q.prompt)}</div>${control}${explanation}</article>`;
}
function dailyDraftKey(sessionId,questionId){return `french-daily-draft-${sessionId}-${questionId}`}
function readDailyDraft(sessionId,questionId){try{return localStorage.getItem(dailyDraftKey(sessionId,questionId))||''}catch(_error){return state.answers[questionId]||''}}
function writeDailyDraft(sessionId,questionId,value){state.answers[questionId]=value;try{value?localStorage.setItem(dailyDraftKey(sessionId,questionId),value):localStorage.removeItem(dailyDraftKey(sessionId,questionId))}catch(_error){}}
function clearDailyDraft(sessionId,questionId){delete state.answers[questionId];try{localStorage.removeItem(dailyDraftKey(sessionId,questionId))}catch(_error){}}
function captureDailyDraft(event){const question=state.today.questions[0],value=event.target.value;writeDailyDraft(state.today.id,question.id,value);document.querySelector('#daily-answer').disabled=!value.trim()}
async function startDaily(){const button=document.querySelector('#daily-start');button.disabled=true;setStatus('Démarrage du chronomètre…');try{state.today=await api(`/api/sessions/${state.today.id}/start`,{method:'POST',body:'{}'});renderToday();setStatus('Le chronomètre a démarré.')}catch(error){button.disabled=false;setStatus(error.message,true)}}
function startDailyTimer(){const timer=document.querySelector('#daily-timer'),bar=document.querySelector('#daily-timebar-fill'),box=document.querySelector('.daily-timing'),deadline=Date.parse(state.today.question_deadline_at),limit=state.today.question_time_limit_seconds*1000;const tick=()=>{const remaining=Math.max(0,deadline-Date.now()),seconds=Math.ceil(remaining/1000),minutes=Math.floor(seconds/60);timer.textContent=`${minutes}:${String(seconds%60).padStart(2,'0')}`;bar.style.width=`${Math.min(100,remaining/limit*100)}%`;box.classList.toggle('urgent',remaining<=10000);if(remaining<=0&&!state.dailySubmitting){clearInterval(state.dailyTimer);state.dailyTimer=null;submitDailyAnswer(true)}};tick();if(!state.dailySubmitting)state.dailyTimer=setInterval(tick,250)}
async function submitDailyAnswer(timedOut){if(state.dailySubmitting)return;const s=state.today,q=s.questions[0],answer=timedOut?'':readDailyDraft(s.id,q.id);if(!timedOut&&!answer.trim())return;state.dailySubmitting=true;clearInterval(state.dailyTimer);state.dailyTimer=null;const button=document.querySelector('#daily-answer');if(button)button.disabled=true;setStatus(timedOut?'Temps écoulé · réponse non répondue enregistrée…':s.current_position===s.question_count?'Envoi final et correction…':'Réponse enregistrée · question suivante…');try{state.today=await api(`/api/sessions/${s.id}/answer`,{method:'POST',body:JSON.stringify({question_id:q.id,answer})});clearDailyDraft(s.id,q.id);state.dailySubmitting=false;renderToday();if(state.today.status==='completed'){setStatus(`Séance corrigée : ${state.today.score}/${state.today.question_count}.`);window.scrollTo({top:0,behavior:'smooth'})}else if(timedOut){setStatus('Temps écoulé : la question a été comptée comme non répondue.')}}catch(error){state.dailySubmitting=false;setStatus(error.message,true);try{state.today=await api(`/api/sessions/${s.id}`);renderToday()}catch(_refreshError){if(button)button.disabled=false}}}

async function showHistory(){setStatus('Chargement…');try{state.historyItems=await api('/api/history');const fallback=new Date().toISOString().slice(0,10),latest=state.historyItems[0]?.study_date||fallback;state.historyMonth=new Date(`${latest.slice(0,7)}-01T12:00:00Z`);state.historySelectedDate=latest;renderHistoryCalendar();setStatus('')}catch(e){setStatus(e.message,true)}}
function renderHistoryCalendar(){const month=state.historyMonth,year=month.getUTCFullYear(),monthIndex=month.getUTCMonth(),first=(new Date(Date.UTC(year,monthIndex,1)).getUTCDay()+6)%7,days=new Date(Date.UTC(year,monthIndex+1,0)).getUTCDate(),byDate=Object.groupBy?Object.groupBy(state.historyItems,item=>item.study_date):state.historyItems.reduce((groups,item)=>{(groups[item.study_date]??=[]).push(item);return groups},{}),cells=[];for(let blank=0;blank<first;blank++)cells.push('<span class="calendar-day empty-day"></span>');for(let day=1;day<=days;day++){const key=`${year}-${String(monthIndex+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,items=byDate[key]||[],types=[...new Set(items.map(item=>item.activity_type||'daily'))];cells.push(`<button class="calendar-day ${items.length?'has-activity':''} ${state.historySelectedDate===key?'selected':''}" data-calendar-date="${key}" ${items.length?'':'disabled'}><span>${day}</span><span class="calendar-dots">${types.map(type=>`<i class="dot ${type}"></i>`).join('')}</span></button>`)}const selected=byDate[state.historySelectedDate]||[],labels={daily:'10 questions',reading:'Lecture',writing:'Écriture'};view.innerHTML=`<div class="history-shell"><h1 class="section-title">Historique</h1><p class="section-subtitle">Choisissez une date pour retrouver vos activités, réponses et corrections.</p><div class="history-layout"><section class="calendar panel"><header><button class="secondary" data-month-step="-1" aria-label="Mois précédent">←</button><h2>${new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'}).format(month)}</h2><button class="secondary" data-month-step="1" aria-label="Mois suivant">→</button></header><div class="calendar-weekdays">${['L','M','M','J','V','S','D'].map(day=>`<span>${day}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div><div class="calendar-legend"><span><i class="dot daily"></i>10 questions</span><span><i class="dot reading"></i>Lecture</span><span><i class="dot writing"></i>Écriture</span></div></section><section class="day-activities"><h2>${esc(formatDate(state.historySelectedDate))}</h2>${selected.length?[...selected].sort((a,b)=>({daily:0,reading:1,writing:2}[a.activity_type||'daily']-({daily:0,reading:1,writing:2}[b.activity_type||'daily']))).map(item=>historyActivityCard(item,labels)).join(''):'<div class="empty panel">Aucune activité enregistrée ce jour-là.</div>'}</section></div></div>`;bindCommon();view.querySelectorAll('[data-calendar-date]').forEach(button=>button.addEventListener('click',()=>{state.historySelectedDate=button.dataset.calendarDate;renderHistoryCalendar()}));view.querySelectorAll('[data-month-step]').forEach(button=>button.addEventListener('click',()=>{state.historyMonth=new Date(Date.UTC(year,monthIndex+Number(button.dataset.monthStep),1,12));const prefix=`${state.historyMonth.getUTCFullYear()}-${String(state.historyMonth.getUTCMonth()+1).padStart(2,'0')}`;state.historySelectedDate=state.historyItems.find(item=>item.study_date.startsWith(prefix))?.study_date||`${prefix}-01`;renderHistoryCalendar()}));view.querySelectorAll('[data-activity]').forEach(button=>button.addEventListener('click',()=>openHistoryActivity(button.dataset.activity,button.dataset.id)))}
function historyActivityCard(item,labels){const type=item.activity_type||'daily',unit=type==='daily'?'/10':type==='reading'?'/4':item.score>20?'/100':'/20',done=item.status==='completed',titles={daily:'Séance quotidienne',reading:item.title||'Compréhension écrite',writing:item.title||'Production écrite'};return `<article class="panel history-row"><div><span class="pill activity-${type}">${labels[type]}</span><h3>${esc(titles[type])}</h3><p class="activity-status">${done?'Terminée · réponses et correction disponibles':'Prête · pas encore envoyée'}</p></div><div class="score">${item.score==null?'—':`${item.score}${unit}`}</div><button class="secondary" data-activity="${type}" data-id="${item.id}">${done?'Voir les réponses':'Ouvrir'}</button></article>`}
function openHistoryActivity(type,id){if(type==='daily')return showSession(id);if(type==='reading')return showReading(id);return showWriting(id)}
async function showSession(id){setStatus('Chargement…');try{state.today=await api(`/api/sessions/${id}`);renderToday();setStatus('')}catch(e){setStatus(e.message,true)}}
async function showReview(){setStatus('Chargement…');try{const [mistakes,grammar,conjugations]=await Promise.all([api('/api/mistakes'),api('/api/grammar'),api('/api/conjugations')]);state.reviewMistakes=mistakes;state.reviewChallenge=null;state.reviewConjugations=conjugations;state.reviewShowAll=false;renderReview(mistakes,grammar);renderReviewLearningTools(conjugations);setStatus('')}catch(e){setStatus(e.message,true)}}
function renderReview(mistakes,grammar){const priorities=[...grammar].sort((a,b)=>(b.mistake_count/b.attempt_count)-(a.mistake_count/a.attempt_count)||b.mistake_count-a.mistake_count),writingCount=mistakes.filter(item=>item.kind==='writing').length,lastDate=mistakes[0]?.study_date;view.innerHTML=`<div class="review-heading"><div><h1 class="section-title">Erreurs & grammaire</h1><p class="section-subtitle">Commencez par les notions les plus fragiles, puis rouvrez une erreur pour comprendre et mémoriser la correction.</p></div>${mistakes.length?`<div class="review-stats"><div><strong>${mistakes.length}</strong><span>erreur${mistakes.length===1?'':'s'}</span></div><div><strong>${priorities.length}</strong><span>notion${priorities.length===1?'':'s'}</span></div><div><strong>${writingCount}</strong><span>en écriture</span></div></div>`:''}</div>${mistakes.length?`<div class="review-workspace"><section class="review-priorities"><div class="review-section-head"><div><span class="eyebrow">Priorité</span><h2>Notions à renforcer</h2></div><span class="review-date">${lastDate?`Dernière erreur · ${esc(formatShortDate(lastDate))}`:''}</span></div><div class="review-grammar-list">${priorities.map((item,index)=>grammarReviewCard(item,index===0)).join('')}</div></section><section class="review-mistakes"><div class="review-section-head"><div><span class="eyebrow">Pratique</span><h2>Erreurs à revoir</h2></div><span id="review-visible-count">${mistakes.length} affichées</span></div><div class="review-filters" role="group" aria-label="Filtrer les erreurs"><button class="review-filter active" data-review-filter="all">Toutes</button><button class="review-filter" data-review-filter="question">Questions</button><button class="review-filter" data-review-filter="writing">Écriture</button></div><div class="review-error-list">${mistakes.map((item,index)=>mistakeReviewCard(item,index===0)).join('')}</div></section></div>`:`<div class="panel review-empty"><span class="review-empty-mark">✓</span><div><h2>Aucune erreur à revoir</h2><p>Terminez une séance ou une production écrite : vos corrections apparaîtront ici, classées par notion.</p><div class="review-empty-actions"><button class="primary" data-view="today">Faire les 10 questions</button><button class="secondary" data-view="writing">S’entraîner à écrire</button></div></div></div>`}`;bindCommon();bindReviewFilters()}
function grammarReviewCard(item,open){const success=Math.max(0,item.attempt_count-item.mistake_count),mastery=Math.round(success/item.attempt_count*100);return `<details class="grammar-review" ${open?'open':''}><summary><div><span class="priority-count">${item.mistake_count}/${item.attempt_count}</span><strong>${esc(item.title_fr)}</strong></div><div class="mastery"><span>${mastery}% acquis</span><progress max="100" value="${mastery}" aria-label="Maîtrise : ${mastery}%"></progress></div></summary><div class="grammar-review-body"><p>${esc(item.explanation_fr)}</p>${zhHint(item.explanation_zh,'Voir l’explication chinoise')}<p class="example">${esc(item.example_fr)} ${speakButton(item.example_fr,'Écouter')}</p></div></details>`}
function mistakeReviewCard(item,open){const kind=item.kind==='writing'?'writing':'question',kindLabel=kind==='writing'?'Écriture':'Question',spoken=kind==='writing'?item.answer:completedQuestion(item);return `<details class="mistake-review" data-review-kind="${kind}" ${open?'open':''}><summary><div class="mistake-meta"><span class="pill activity-${kind==='writing'?'writing':'daily'}">${kindLabel}</span><span>${esc(formatShortDate(item.study_date))}</span></div><strong>${esc(item.prompt)}</strong><div class="quick-correction"><span class="bad">${esc(item.user_answer||'—')}</span><span aria-hidden="true">→</span><span class="good">${esc(item.answer)}</span></div></summary><div class="mistake-detail"><p>${esc(item.explanation_fr)}</p>${zhHint(item.explanation_zh,'Voir l’explication chinoise')}<p class="example"><strong>Exemple à retenir :</strong> ${esc(spoken)} ${speakButton(spoken,'Écouter la correction')}</p></div></details>`}
function bindReviewFilters(){const buttons=view.querySelectorAll('[data-review-filter]'),cards=view.querySelectorAll('[data-review-kind]'),counter=document.querySelector('#review-visible-count');buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(item=>item.classList.toggle('active',item===button));let visible=0;cards.forEach(card=>{const show=button.dataset.reviewFilter==='all'||card.dataset.reviewKind===button.dataset.reviewFilter;card.hidden=!show;if(show)visible+=1});if(counter)counter.textContent=`${visible} affichée${visible===1?'':'s'}`}))}
function renderReviewLearningTools(conjugations){const heading=view.querySelector('.review-heading');if(!heading)return;heading.insertAdjacentHTML('afterend',`<div class="review-learning-tools"><section class="panel review-challenge"><div class="challenge-copy"><span class="eyebrow">Révision active</span><h2>Défi éclair · jusqu’à 5 erreurs</h2><p>Une question à la fois, avec correction immédiate. Aucun résultat n’est enregistré.</p></div><div id="challenge-stage" class="challenge-stage"></div></section><section class="review-conjugations"><div class="review-section-head"><div><span class="eyebrow">Synthèse personnalisée</span><h2>Conjugaisons à consolider</h2></div><span>${conjugations.length?`${conjugations.length} verbe${conjugations.length===1?'':'s'} identifié${conjugations.length===1?'':'s'}`:'Analyse des erreurs'}</span></div>${conjugations.length?`${conjugations.length>4?`<div class="conjugation-toolbar"><label for="conjugation-search">Rechercher un verbe</label><input id="conjugation-search" type="search" autocomplete="off" placeholder="Ex. aller, faire…"><span>Classés par fréquence d’erreur</span></div>`:'<p class="conjugation-order">Classés par fréquence d’erreur</p>'}<div id="conjugation-grid" class="conjugation-grid"></div><div id="conjugation-list-footer" class="conjugation-list-footer"></div>`:`<div class="panel conjugation-empty">Aucune faiblesse de conjugaison fiable n’est encore identifiable. Les tableaux apparaîtront après une erreur contenant un verbe reconnu.</div>`}</section></div>`);renderConjugationList();renderReviewChallenge();document.querySelector('#conjugation-search')?.addEventListener('input',renderConjugationList)}
function renderConjugationList(){const grid=document.querySelector('#conjugation-grid'),footer=document.querySelector('#conjugation-list-footer');if(!grid)return;const query=normalizeReviewAnswer(document.querySelector('#conjugation-search')?.value),matches=state.reviewConjugations.filter(item=>!query||normalizeReviewAnswer(item.verb).includes(query)),visible=query||state.reviewShowAll?matches:matches.slice(0,4);grid.innerHTML=visible.length?visible.map((item,index)=>conjugationCard(item,index===0)).join(''):'<div class="panel conjugation-empty">Aucun verbe ne correspond à cette recherche.</div>';if(footer){const hidden=matches.length-visible.length;footer.innerHTML=state.reviewConjugations.length>4&&!query?`<span>${visible.length} sur ${matches.length} verbes affichés</span><button class="secondary" id="toggle-conjugations">${state.reviewShowAll?'Afficher les priorités':'Voir tous les verbes'}${hidden?` (${hidden})`:''}</button>`:'';document.querySelector('#toggle-conjugations')?.addEventListener('click',()=>{state.reviewShowAll=!state.reviewShowAll;renderConjugationList()})}bindSpeakButtons(grid)}
function conjugationCard(item,open){return `<details class="conjugation-card" ${open?'open':''}><summary><div><strong>${esc(item.verb)}</strong><span>${item.mistake_count} erreur${item.mistake_count===1?'':'s'} repérée${item.mistake_count===1?'':'s'}</span></div><div class="tense-tags">${item.tenses.map(tense=>`<span>${esc(tense.name)}</span>`).join('')}</div></summary><div class="conjugation-body">${zhHint(item.translation_zh,'Afficher le sens en chinois')}${item.tenses.map(tense=>conjugationTable(tense)).join('')}${item.examples.length?`<div class="conjugation-examples"><strong>Erreurs à l’origine de cette synthèse</strong>${item.examples.map(example=>`<p>${esc(example.prompt)} <span>→ ${esc(example.answer)}</span></p>`).join('')}</div>`:''}</div></details>`}
function conjugationTable(tense){const rows=Object.entries(tense.forms),speech=rows.map(([pronoun,form])=>`${pronoun} ${form}`).join('. ');return `<section class="tense-table"><header><div><h3>${esc(tense.name)}</h3><span>${tense.mistake_count} erreur${tense.mistake_count===1?'':'s'} liée${tense.mistake_count===1?'':'s'}</span></div>${speakButton(speech,`Écouter ${tense.name}`)}</header><table><tbody>${rows.map(([pronoun,form])=>`<tr><th>${esc(pronoun)}</th><td>${esc(form)}</td></tr>`).join('')}</tbody></table></section>`}
function shuffled(items){const result=[...items];for(let index=result.length-1;index>0;index-=1){const swap=Math.floor(Math.random()*(index+1));[result[index],result[swap]]=[result[swap],result[index]]}return result}
let reviewChallengeUsageCache=null,reviewChallengeDismissedCache=null;
function reviewChallengeDay(){const now=new Date();return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}
function reviewChallengeUsage(){const day=reviewChallengeDay();if(reviewChallengeUsageCache?.day===day)return reviewChallengeUsageCache;try{const stored=JSON.parse(localStorage.getItem('french-review-challenge-usage')||'null');reviewChallengeUsageCache=stored?.day===day&&stored.appearances&&typeof stored.appearances==='object'?stored:{day,appearances:{}}}catch(error){reviewChallengeUsageCache={day,appearances:{}}}return reviewChallengeUsageCache}
function persistReviewChallengeUsage(){try{localStorage.setItem('french-review-challenge-usage',JSON.stringify(reviewChallengeUsage()))}catch(error){}}
function reviewChallengeDismissedIds(){if(reviewChallengeDismissedCache)return reviewChallengeDismissedCache;try{const stored=JSON.parse(localStorage.getItem('french-review-challenge-dismissed')||'[]');reviewChallengeDismissedCache=new Set(Array.isArray(stored)?stored.map(String):[])}catch(error){reviewChallengeDismissedCache=new Set()}return reviewChallengeDismissedCache}
function persistReviewChallengeDismissedIds(){try{localStorage.setItem('french-review-challenge-dismissed',JSON.stringify([...reviewChallengeDismissedIds()]))}catch(error){}}
function reviewChallengeCandidates(){const appearances=reviewChallengeUsage().appearances,dismissed=reviewChallengeDismissedIds();return state.reviewMistakes.filter(item=>!dismissed.has(String(item.id))&&Number(appearances[item.id]||0)<2)}
function startReviewChallenge(){const items=shuffled(reviewChallengeCandidates()).slice(0,5);if(!items.length){state.reviewChallenge=null;renderReviewChallenge();return}const usage=reviewChallengeUsage();items.forEach(item=>{usage.appearances[item.id]=Number(usage.appearances[item.id]||0)+1});persistReviewChallengeUsage();state.reviewChallenge={items,index:0,score:0,answered:false,selected:'',correct:false,finished:false,dismissed:false};renderReviewChallenge()}
function normalizeReviewAnswer(value){return String(value||'').normalize('NFC').trim().toLocaleLowerCase('fr-FR').replaceAll('’',"'").replace(/\s+/g,' ')}
function answerReviewChallenge(value){const challenge=state.reviewChallenge;if(!challenge||challenge.answered)return;const item=challenge.items[challenge.index];challenge.selected=String(value||'').trim();challenge.correct=normalizeReviewAnswer(challenge.selected)===normalizeReviewAnswer(item.answer);challenge.answered=true;if(challenge.correct)challenge.score+=1;renderReviewChallenge()}
function dismissReviewChallengeItem(){const challenge=state.reviewChallenge;if(!challenge?.answered||!challenge.correct)return;const item=challenge.items[challenge.index];reviewChallengeDismissedIds().add(String(item.id));persistReviewChallengeDismissedIds();challenge.dismissed=true;renderReviewChallenge()}
function nextReviewChallenge(){const challenge=state.reviewChallenge;if(challenge.index+1>=challenge.items.length)challenge.finished=true;else{challenge.index+=1;challenge.answered=false;challenge.selected='';challenge.correct=false;challenge.dismissed=false}renderReviewChallenge()}
function renderReviewChallenge(){const stage=document.querySelector('#challenge-stage');if(!stage)return;const challenge=state.reviewChallenge;if(!challenge){const count=Math.min(5,reviewChallengeCandidates().length),emptyLabel=state.reviewMistakes.length?'Limite quotidienne atteinte':'Pas encore d’erreur';stage.innerHTML=`<div class="challenge-intro"><strong>${count||'—'} question${count===1?'':'s'} disponible${count===1?'':'s'} aujourd’hui</strong><button class="primary" id="start-challenge" ${count?'':'disabled'}>${count?'Commencer le défi':emptyLabel}</button></div>`;document.querySelector('#start-challenge')?.addEventListener('click',startReviewChallenge);return}if(challenge.finished){const hasMore=reviewChallengeCandidates().length>0;stage.innerHTML=`<div class="challenge-finish"><span class="challenge-score">${challenge.score}/${challenge.items.length}</span><div><strong>Série terminée</strong><p>Ce résultat reste uniquement à l’écran et n’est pas ajouté à votre historique.</p></div><button class="secondary" id="restart-challenge" ${hasMore?'':'disabled'}>${hasMore?'Nouvelle série':'Limite quotidienne atteinte'}</button></div>`;document.querySelector('#restart-challenge')?.addEventListener('click',startReviewChallenge);return}const item=challenge.items[challenge.index],isChoice=item.kind==='mcq'&&item.options?.length,kind=item.kind==='writing'?'Correction d’écriture':isChoice?'Choix multiple':'Texte à compléter',correctSentence=item.kind==='writing'?item.answer:completedQuestion(item);let interaction;if(challenge.answered){const selectedNote=isChoice?item.option_explanations?.[challenge.selected]:'';interaction=`<div class="challenge-feedback ${challenge.correct?'correct':'incorrect'}"><strong>${challenge.correct?'✓ Bonne réponse':'✕ À revoir'}</strong><div class="quick-correction"><span class="bad">${esc(challenge.selected||'—')}</span><span aria-hidden="true">→</span><span class="good">${esc(item.answer)}</span></div>${selectedNote?`<p>${esc(selectedNote)}</p>`:''}<p>${esc(item.explanation_fr)}</p>${zhHint(item.explanation_zh)}<p class="example"><strong>Phrase correcte :</strong> ${esc(correctSentence)} ${speakButton(correctSentence,'Écouter')}</p><div class="challenge-feedback-actions">${challenge.correct?`<button class="challenge-dismiss" id="dismiss-challenge-item" aria-label="Retirer définitivement cette question des prochains défis" ${challenge.dismissed?'disabled':''}><span aria-hidden="true">🗑</span> ${challenge.dismissed?'Question retirée':'Ne plus proposer'}</button>`:''}<button class="primary" id="next-challenge">${challenge.index+1===challenge.items.length?'Voir le résultat':'Question suivante'}</button></div></div>`}else if(isChoice){interaction=`<div class="challenge-options">${item.options.map(option=>`<button data-challenge-answer="${esc(option)}">${esc(option)}</button>`).join('')}</div>`}else{interaction=`<form class="challenge-fill"><label for="challenge-answer">Votre correction</label><div><input id="challenge-answer" autocomplete="off" lang="fr" placeholder="Écrivez la réponse correcte"><button class="primary">Vérifier</button></div></form>`}stage.innerHTML=`<article class="challenge-question"><div class="challenge-progress"><span>Question ${challenge.index+1}/${challenge.items.length}</span><strong>${challenge.score} correcte${challenge.score===1?'':'s'}</strong></div><span class="pill activity-daily">${kind}</span><h3 lang="fr">${esc(item.prompt)}</h3>${interaction}</article>`;stage.querySelectorAll('[data-challenge-answer]').forEach(button=>button.addEventListener('click',()=>answerReviewChallenge(button.dataset.challengeAnswer)));stage.querySelector('.challenge-fill')?.addEventListener('submit',event=>{event.preventDefault();answerReviewChallenge(document.querySelector('#challenge-answer').value)});document.querySelector('#dismiss-challenge-item')?.addEventListener('click',dismissReviewChallengeItem);document.querySelector('#next-challenge')?.addEventListener('click',nextReviewChallenge);bindSpeakButtons(stage);stage.querySelector('input')?.focus()}
function bindSpeakButtons(root){root?.querySelectorAll('[data-speak]').forEach(button=>button.addEventListener('click',()=>speak(button.dataset.speak,button)))}
function vocabularyMonthKey(month){return `${month.getUTCFullYear()}-${String(month.getUTCMonth()+1).padStart(2,'0')}`}
async function showVocabulary(){if(!state.vocabularyMonth){const today=new Date();state.vocabularyMonth=new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),1))}await loadVocabularyMonth()}
async function loadVocabularyMonth(){setStatus('Chargement du vocabulaire…');try{const key=vocabularyMonthKey(state.vocabularyMonth);state.vocabularyWords=await api(`/api/vocabulary?month=${key}`);const dates=[...new Set(state.vocabularyWords.map(word=>word.study_date))].sort();if(!state.vocabularySelectedDate||!state.vocabularySelectedDate.startsWith(key)||!dates.includes(state.vocabularySelectedDate))state.vocabularySelectedDate=dates.at(-1)||`${key}-01`;renderVocabularyCalendar();setStatus('')}catch(error){setStatus(error.message,true)}}
function renderVocabularyCalendar(){const month=state.vocabularyMonth,year=month.getUTCFullYear(),monthIndex=month.getUTCMonth(),first=(new Date(Date.UTC(year,monthIndex,1)).getUTCDay()+6)%7,days=new Date(Date.UTC(year,monthIndex+1,0)).getUTCDate(),byDate=state.vocabularyWords.reduce((groups,word)=>{(groups[word.study_date]??=[]).push(word);return groups},{}),cells=[];for(let blank=0;blank<first;blank++)cells.push('<span class="vocabulary-day empty-day"></span>');for(let day=1;day<=days;day++){const key=`${year}-${String(monthIndex+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,words=byDate[key]||[],starred=words.filter(word=>word.starred).length;cells.push(`<button class="vocabulary-day ${words.length?'has-words':''} ${state.vocabularySelectedDate===key?'selected':''}" data-vocabulary-date="${key}" ${words.length?'':'disabled'}><span>${day}</span>${words.length?`<small>${words.length} mots</small><span class="vocabulary-day-stars" aria-label="${starred} favori${starred===1?'':'s'}">${starred?'★'.repeat(Math.min(starred,3)):''}</span>`:''}</button>`)}const monthWords=state.vocabularyWords,monthStars=monthWords.filter(word=>word.starred).length,selectedWords=byDate[state.vocabularySelectedDate]||[],visibleWords=state.vocabularyStarredOnly?selectedWords.filter(word=>word.starred):selectedWords;view.innerHTML=`<div class="vocabulary-page"><header class="vocabulary-hero"><div><span class="eyebrow">Carnet personnel</span><h1>Vocabulaire</h1><p>Retrouvez les mots appris chaque jour et gardez les plus importants avec une étoile.</p></div><div class="vocabulary-stats"><div><strong>${monthWords.length}</strong><span>mots ce mois</span></div><div><strong>${monthStars}</strong><span>favori${monthStars===1?'':'s'}</span></div></div></header><div class="vocabulary-layout"><section class="panel vocabulary-calendar"><header><button class="secondary" data-vocabulary-month="-1" aria-label="Mois précédent">←</button><h2>${new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'}).format(month)}</h2><button class="secondary" data-vocabulary-month="1" aria-label="Mois suivant">→</button></header><div class="calendar-weekdays">${['L','M','M','J','V','S','D'].map(day=>`<span>${day}</span>`).join('')}</div><div class="vocabulary-calendar-grid">${cells.join('')}</div><p class="vocabulary-calendar-note">Les jours remplis correspondent aux mots de votre séance quotidienne.</p></section><section class="vocabulary-day-panel"><div class="vocabulary-day-head"><div><span class="eyebrow">${selectedWords.length?'Mots du jour':'Aucun mot'}</span><h2>${formatDate(state.vocabularySelectedDate)}</h2></div><button class="vocabulary-filter ${state.vocabularyStarredOnly?'active':''}" data-vocabulary-filter aria-pressed="${state.vocabularyStarredOnly}"><span aria-hidden="true">★</span> ${state.vocabularyStarredOnly?'Tous les mots':'Favoris uniquement'}</button></div>${visibleWords.length?`<div class="vocabulary-card-list">${visibleWords.map(vocabularyCard).join('')}</div>`:`<div class="panel empty vocabulary-empty">${selectedWords.length?'Aucun favori pour cette date. Désactivez le filtre pour revoir tous les mots.':'Aucun vocabulaire enregistré pour cette date.'}</div>`}</section></div></div>`;bindVocabularyControls();bindCommon()}
function vocabularyCard(word){return `<article class="vocab-card ${word.starred?'starred':''}" data-vocabulary-id="${word.id}"><div class="vocab-head"><div><span class="pill ${word.category}">${word.category==='community'?'Communauté':'Quotidien'}</span><div class="vocab-word" lang="fr">${esc(word.word)}</div><div class="pos">${esc(word.part_of_speech)}</div></div><div class="vocabulary-card-actions"><button class="vocabulary-star" data-vocabulary-star="${word.id}" aria-pressed="${word.starred}" aria-label="${word.starred?'Retirer':'Ajouter'} ${esc(word.word)} ${word.starred?'des':'aux'} favoris"><span aria-hidden="true">${word.starred?'★':'☆'}</span></button>${speakButton(word.word,'Écouter le mot')}</div></div><p lang="fr">${esc(word.definition_fr)}</p><p class="example" lang="fr">${esc(word.example_fr)} ${speakButton(word.example_fr,'Écouter la phrase')}</p>${zhHint(`${word.definition_zh} · ${word.example_zh}`)}${word.source_name?`<p class="source">Contexte : ${word.source_url?`<a href="${esc(word.source_url)}" target="_blank" rel="noreferrer">${esc(word.source_name)}</a>`:esc(word.source_name)}</p>`:''}</article>`}
function bindVocabularyControls(){view.querySelectorAll('[data-vocabulary-month]').forEach(button=>button.addEventListener('click',()=>{state.vocabularyMonth=new Date(Date.UTC(state.vocabularyMonth.getUTCFullYear(),state.vocabularyMonth.getUTCMonth()+Number(button.dataset.vocabularyMonth),1));loadVocabularyMonth()}));view.querySelectorAll('[data-vocabulary-date]').forEach(button=>button.addEventListener('click',()=>{state.vocabularySelectedDate=button.dataset.vocabularyDate;renderVocabularyCalendar()}));document.querySelector('[data-vocabulary-filter]')?.addEventListener('click',()=>{state.vocabularyStarredOnly=!state.vocabularyStarredOnly;renderVocabularyCalendar()});view.querySelectorAll('[data-vocabulary-star]').forEach(button=>button.addEventListener('click',()=>toggleVocabularyStar(Number(button.dataset.vocabularyStar))))}
async function toggleVocabularyStar(id){const selected=state.vocabularyWords.find(word=>word.id===id);if(!selected)return;const next=!selected.starred,key=String(selected.word).normalize('NFC').toLocaleLowerCase('fr-FR').replaceAll('’',"'").trim();state.vocabularyWords.forEach(word=>{const wordKey=String(word.word).normalize('NFC').toLocaleLowerCase('fr-FR').replaceAll('’',"'").trim();if(wordKey===key)word.starred=next});renderVocabularyCalendar();document.querySelector(`[data-vocabulary-star="${id}"]`)?.focus();try{await api(`/api/vocabulary/${id}/star`,{method:'POST',body:JSON.stringify({starred:next})});setStatus(next?`${selected.word} ajouté aux favoris.`:`${selected.word} retiré des favoris.`)}catch(error){state.vocabularyWords.forEach(word=>{const wordKey=String(word.word).normalize('NFC').toLocaleLowerCase('fr-FR').replaceAll('’',"'").trim();if(wordKey===key)word.starred=!next});renderVocabularyCalendar();setStatus(error.message,true)}}
async function showReading(id=null){setStatus('Préparation de la lecture…');try{const task=await api(id?`/api/tasks/${id}`:'/api/tasks/reading');renderReading(task);setStatus('')}catch(e){setStatus(e.message,true)}}
function readingStorageKey(id){return `french-reading-answers-${id}`}
function loadReadingAnswers(id){try{const value=JSON.parse(localStorage.getItem(readingStorageKey(id))||'{}');return value&&typeof value==='object'?value:{}}catch(error){return{}}}
function saveReadingAnswers(id){try{localStorage.setItem(readingStorageKey(id),JSON.stringify(state.readingAnswers))}catch(error){}}
function clearReadingTimer(){if(state.readingTimer)clearInterval(state.readingTimer);state.readingTimer=null;state.readingDeadline=null}
function formatReadingTime(seconds){const value=Math.max(0,Math.ceil(seconds)),minutes=Math.floor(value/60),rest=value%60;return `${String(minutes).padStart(2,'0')}:${String(rest).padStart(2,'0')}`}
function renderReadingStart(task){clearReadingTimer();state.readingSubmitting=false;const seconds=task.content.time_limit_seconds,minutes=Math.ceil(seconds/60);view.innerHTML=`<div class="reading-page"><header class="task-hero reading-hero"><div class="reading-kicker"><span class="pill activity-reading">Lecture · B2</span><span class="reading-ready">Exercice chronométré</span></div><h1>${esc(task.title)}</h1></header><section class="panel reading-start"><span class="reading-start-clock">${minutes}:00</span><h2>Lecture limitée à ${minutes} minutes</h2><p>L’article et les quatre questions apparaîtront uniquement après votre confirmation. Le chronomètre ne peut pas être mis en pause.</p><ul><li>Vous pouvez rendre votre copie avant la fin.</li><li>Les questions sans réponse comptent comme incorrectes.</li><li>À 00:00, vos réponses sélectionnées sont envoyées automatiquement.</li></ul><button class="primary" id="start-reading">Commencer la lecture</button></section></div>`;document.querySelector('#start-reading').addEventListener('click',()=>startReading(task.id))}
async function startReading(id){if(!confirm('Le chronomètre démarrera immédiatement et ne pourra pas être mis en pause. Commencer maintenant ?'))return;const button=document.querySelector('#start-reading');button.disabled=true;setStatus('Démarrage du chronomètre…');try{const task=await api(`/api/reading/${id}/start`,{method:'POST',body:'{}'});renderReading(task);setStatus('Le chronomètre a démarré.')}catch(error){button.disabled=false;setStatus(error.message,true)}}
function bindReadingTimer(task){clearReadingTimer();state.readingTaskId=task.id;state.readingDeadline=new Date(task.deadline_at).getTime();state.readingAnswers=loadReadingAnswers(task.id);const tick=()=>{const seconds=(state.readingDeadline-Date.now())/1000,label=document.querySelector('#reading-countdown');if(label){label.textContent=formatReadingTime(seconds);label.closest('.reading-timing')?.classList.toggle('urgent',seconds<=60)}if(seconds<=0){clearReadingTimer();submitReading(task.id,true)}};tick();if(state.readingDeadline>Date.now())state.readingTimer=setInterval(tick,250)}
function renderReading(task){if(task.status==='ready')return renderReadingStart(task);const c=task.content,done=task.status==='completed',feedback=task.submission?.feedback,wordCount=(c.article_fr.match(/[A-Za-zÀ-ÿ]+(?:['’-][A-Za-zÀ-ÿ]+)*/g)||[]).length,minutes=Math.max(1,Math.ceil(wordCount/180)),paragraphs=readingParagraphs(c.article_fr);if(done){clearReadingTimer();try{localStorage.removeItem(readingStorageKey(task.id))}catch(error){}}else state.readingAnswers=loadReadingAnswers(task.id);view.innerHTML=`<div class="reading-page"><header class="task-hero reading-hero"><div class="reading-kicker"><span class="pill activity-reading">Lecture · B2</span>${done?`<span class="reading-complete">✓ Terminée · ${task.score}/4</span>`:''}</div><h1>${esc(c.title)}</h1>${!done?`<div class="reading-timing"><span>Temps restant</span><strong id="reading-countdown">--:--</strong><small>Envoi automatique à 00:00</small></div>`:''}<div class="reading-meta"><span>${wordCount} mots</span><span>≈ ${minutes} min</span><span>4 questions</span><span>${esc(c.source_name||'Source contrôlée')}${c.source_url?` · <a href="${esc(c.source_url)}" target="_blank" rel="noreferrer">Source originale ↗</a>`:''}</span></div></header><div class="reading-workspace"><article class="panel reading-text" lang="fr"><header class="reader-toolbar"><div><span class="eyebrow">Article</span><span id="reader-size-state" aria-live="polite">Taille normale</span></div><div class="reader-tools"><button class="reader-size" data-reader-size="-1" aria-label="Réduire la taille du texte">A−</button><button class="reader-size" data-reader-size="1" aria-label="Agrandir la taille du texte">A+</button>${speakButton(c.article_fr,'Écouter')}</div></header><div class="reading-copy">${paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div></article><aside class="panel reading-glossary"><div class="reading-glossary-head"><span class="eyebrow">Aide à la lecture</span><h2>Mots clés</h2></div>${c.vocabulary.map(v=>`<article class="glossary-item"><div><strong>${esc(v.word)}</strong>${speakButton(v.word,'Écouter le mot')}</div><p>${esc(v.definition_fr)}</p><details class="glossary-translation"><summary>Afficher l’aide en chinois</summary><span lang="zh">${esc(v.definition_zh)}</span></details></article>`).join('')}</aside></div><section class="reading-comprehension"><header class="comprehension-head"><div><span class="eyebrow">Compréhension</span><h2>Vérifiez votre lecture</h2></div><span id="reading-answer-progress">${done?'4 réponses corrigées':'0/4 répondues'}</span></header><div class="reading-questions">${c.questions.map((q,index)=>{const graded=feedback?.questions?.find(item=>item.index===index),chosen=done?feedback?.answers?.[index]:state.readingAnswers[String(index)];return `<article class="panel reading-question ${done?(graded?.is_correct?'correct':'incorrect'):''}" data-reading-question="${index}"><div class="question-number">${index+1}</div><h3>${esc(q.prompt)}</h3><div class="reading-options">${q.options.map(option=>{const selected=chosen===option,correct=done&&q.answer===option;return `<label class="option ${correct?'option-correct':''} ${done&&selected&&!correct?'option-wrong':''}"><input type="radio" name="read-${index}" value="${esc(option)}" ${selected?'checked':''} ${done?'disabled':''}><span>${esc(option)}</span></label>`}).join('')}</div>${done?`<div class="reading-feedback"><strong class="${graded?.is_correct?'good':'bad'}">${graded?.is_correct?'✓ Bonne réponse':'✕ À revoir'}</strong>${!graded?.is_correct?`<p class="correct-answer">Réponse correcte : ${esc(q.answer)}</p>`:''}<p>${esc(q.explanation_fr)}</p>${zhHint(q.explanation_zh,'Voir l’explication chinoise')}</div>`:''}</article>`}).join('')}</div>${done?`<div class="result-banner reading-result"><div><span>Résultat</span><strong>${task.score}/4</strong></div><p>${task.score===4?'Très bonne compréhension. Relisez les explications pour consolider les nuances.':task.score>=2?'Bon travail. Reprenez les cartes marquées « À revoir ».':'Relisez l’article avec les mots clés, puis comparez chaque réponse.'}</p></div>`:`<div class="reading-submit"><span>Vous pouvez rendre avant la fin, même avec des réponses manquantes.</span><button id="submit-reading" class="primary">Rendre maintenant</button></div>`}</section></div>`;bindCommon();bindReadingControls();if(!done){bindReadingAnswers(task.id);bindReadingTimer(task)}}
function readingParagraphs(text){const supplied=text.split(/\n+/).map(item=>item.trim()).filter(Boolean);if(supplied.length>1)return supplied;const sentences=text.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[text],chunk=Math.max(1,Math.ceil(sentences.length/3)),paragraphs=[];for(let index=0;index<sentences.length;index+=chunk)paragraphs.push(sentences.slice(index,index+chunk).join(' ').replace(/\s+/g,' ').trim());return paragraphs}
function bindReadingControls(){const article=document.querySelector('.reading-text'),stateLabel=document.querySelector('#reader-size-state');if(!article)return;let scale=1;const names=['Taille compacte','Taille normale','Taille agrandie'];view.querySelectorAll('[data-reader-size]').forEach(button=>button.addEventListener('click',()=>{scale=Math.max(0,Math.min(2,scale+Number(button.dataset.readerSize)));article.classList.toggle('reading-size-compact',scale===0);article.classList.toggle('reading-size-large',scale===2);stateLabel.textContent=names[scale]}))}
function bindReadingAnswers(taskId){const cards=[...view.querySelectorAll('[data-reading-question]')],counter=document.querySelector('#reading-answer-progress'),button=document.querySelector('#submit-reading');const update=()=>{state.readingAnswers={};cards.forEach((card,index)=>{const checked=card.querySelector('input:checked');if(checked)state.readingAnswers[String(index)]=checked.value;card.classList.toggle('answered',Boolean(checked))});saveReadingAnswers(taskId);const answered=Object.keys(state.readingAnswers).length;counter.textContent=`${answered}/4 répondue${answered===1?'':'s'}`;button.disabled=state.readingSubmitting};cards.forEach(card=>card.querySelectorAll('input').forEach(input=>input.addEventListener('change',update)));button.addEventListener('click',()=>{const unanswered=4-Object.keys(state.readingAnswers).length;if(unanswered&&!confirm(`${unanswered} question${unanswered===1?'':'s'} sans réponse sera${unanswered===1?'':'ont'} comptée${unanswered===1?'':'s'} comme incorrecte${unanswered===1?'':'s'}. Rendre maintenant ?`))return;submitReading(taskId,false)});update()}
async function submitReading(taskId,timedOut=false){if(state.readingSubmitting)return;state.readingSubmitting=true;const button=document.querySelector('#submit-reading');if(button)button.disabled=true;setStatus(timedOut?'Temps écoulé : envoi automatique…':'Correction en cours…');try{const task=await api(`/api/reading/${taskId}/submit`,{method:'POST',body:JSON.stringify({answers:state.readingAnswers})});state.readingSubmitting=false;renderReading(task);setStatus(timedOut?'Temps écoulé : vos réponses ont été envoyées automatiquement.':'Lecture corrigée.')}catch(error){state.readingSubmitting=false;if(button)button.disabled=false;setStatus(error.message,true);if(timedOut)setTimeout(()=>showReading(taskId),1000)}}

function clearWritingPoll(){if(state.writingPoll){clearTimeout(state.writingPoll);state.writingPoll=null}}
function scheduleWritingPoll(taskId){clearWritingPoll();state.writingPoll=setTimeout(async()=>{if(state.view!=='writing')return;try{const task=await api(`/api/tasks/${taskId}`);renderWriting(task);if(task.status==='completed'){try{localStorage.removeItem(`french-writing-draft-${taskId}`)}catch(error){}setStatus('Correction terminée.')}else if(task.status==='grading')setStatus('Votre texte est enregistré. La correction continue en arrière-plan.');else setStatus('La correction n’a pas abouti. Votre texte est conservé : vous pouvez réessayer.',true)}catch(error){setStatus('Connexion interrompue. Nouvelle vérification automatique…',true);scheduleWritingPoll(taskId)}},2000)}
async function showWriting(id=null){setStatus('Préparation du sujet…');try{const task=await api(id?`/api/tasks/${id}`:'/api/tasks/writing');renderWriting(task);if(task.status==='grading')setStatus('Votre texte est enregistré. Vous pouvez quitter cette page : la correction continue.');else if(task.correction_error)setStatus('La précédente tentative n’a pas abouti. Votre texte est conservé : vous pouvez relancer la correction.',true);else setStatus('')}catch(e){setStatus(e.message,true)}}
function writingScoreScale(task){return task.score>20?{total:100,dimension:25}:{total:20,dimension:5}}
function renderModelAnswers(models,title,subtitle){if(!Array.isArray(models)||!models.length)return'';return `<section class="writing-models"><h2>${esc(title)}</h2><p class="section-subtitle">${esc(subtitle)}</p><div class="model-answer-grid">${models.map(model=>`<article class="panel model-answer"><header><div><span class="eyebrow">Réponse modèle · ${esc(model.level)}</span><h3>Niveau ${esc(model.level)}</h3></div><strong>20/20</strong></header><p class="preserve-lines" lang="fr">${esc(model.text)}</p>${Array.isArray(model.vocabulary)&&model.vocabulary.length?`<details class="zh-hint model-vocabulary"><summary>Afficher l’aide en chinois pour le vocabulaire avancé</summary><dl>${model.vocabulary.map(note=>`<div><dt lang="fr">${esc(note.expression_fr)}</dt><dd lang="zh">${esc(note.meaning_zh)}</dd></div>`).join('')}</dl></details>`:''}</article>`).join('')}</div></section>`}
function renderWritingExtensions(content,feedback){const prepared=content.model_answers,sameTheme=feedback.model_answers,guidance=Array.isArray(feedback.optimization_guidance)?feedback.optimization_guidance:[];return `${renderModelAnswers(prepared,'Réponses préparées avec le sujet','Angles choisis avant votre production, indépendamment de votre réponse.')}${renderModelAnswers(sameTheme,'Réponses sur votre thème','Deux modèles qui développent le même choix concret que votre production.')}${guidance.length?`<section class="writing-guidance"><h2>Guide d’optimisation</h2><div class="guidance-list">${guidance.map((item,index)=>`<article class="panel"><span class="guidance-number">${index+1}</span><p lang="fr">${esc(item.advice_fr)}</p><p class="guidance-zh" lang="zh">${esc(item.advice_zh)}</p></article>`).join('')}</div></section>`:''}`}
function renderWriting(task){clearWritingPoll();const c=task.content;if(task.status==='grading'){view.innerHTML=`<div class="writing-page"><header class="task-hero writing-hero"><div class="writing-kicker"><span class="pill activity-writing">Écriture · B1–B2</span><span class="writing-complete">Correction en cours</span></div><h1>${esc(c.title)}</h1></header><article class="panel"><h2>Votre production est enregistrée</h2><p>La correction détaillée continue sur le serveur. Vous pouvez actualiser la page, consulter une autre activité ou fermer cette fenêtre sans interrompre le traitement.</p><p>Cette page vérifiera automatiquement le résultat.</p><button class="primary" data-view="today">Continuer une autre activité</button></article></div>`;bindCommon();scheduleWritingPoll(task.id);return}const done=task.status==='completed',submission=task.submission,feedback=submission?.feedback,scale=writingScoreScale(task);const dimensionLabels={task:'Respect de la consigne',cohesion:'Cohésion',grammar:'Grammaire',vocabulary:'Vocabulaire'};view.innerHTML=`<div class="writing-page ${done?'writing-done':''}"><header class="task-hero writing-hero"><div class="writing-kicker"><span class="pill activity-writing">Écriture · B1–B2</span>${done?`<span class="writing-complete">✓ Corrigée · ${task.score}/${scale.total}</span>`:''}</div><h1>${esc(c.title)}</h1><div class="writing-meta"><span>${c.min_words}–${c.max_words} mots</span><span>Correction détaillée</span><span>Une soumission finale</span></div></header><div class="writing-workspace"><aside class="writing-brief"><article class="panel writing-context"><h2>Situation</h2><p>${esc(c.context_fr)}</p></article><article class="panel writing-prompt"><h2>Consigne</h2><p lang="fr">${esc(c.instructions_fr)}</p>${zhHint(c.instructions_zh)}<p><strong>${c.min_words}–${c.max_words} mots recommandés</strong></p></article></aside>${done?`<section class="writing-results"><article class="panel"><h2>Votre production</h2><p class="preserve-lines">${esc(submission.answer_text)}</p></article><div class="writing-score"><strong>${task.score}/${scale.total}</strong><span>${esc(feedback.summary_fr)}</span>${zhHint(feedback.summary_zh,'Voir le résumé en chinois')}</div><div class="score-grid">${Object.entries(feedback.dimensions).map(([key,item])=>`<article class="panel"><span class="dimension-score">${item.score}/${scale.dimension}</span><h3>${dimensionLabels[key]}</h3><p>${esc(item.comment_fr)}</p>${zhHint(item.comment_zh,'Voir le commentaire chinois')}</article>`).join('')}</div><h2>Corrections ciblées</h2>${feedback.errors.length?`<div class="correction-list">${feedback.errors.map(item=>`<article class="panel correction-item"><p class="before">${esc(item.original)}</p><p class="after">${esc(item.correction)}</p><p>${esc(item.explanation_fr)}</p>${zhHint(item.explanation_zh,'Voir l’explication chinoise')}</article>`).join('')}</div>`:'<div class="panel">Aucune erreur précise relevée.</div>'}<article class="panel corrected-text"><h2>Version corrigée</h2><p class="preserve-lines">${esc(feedback.corrected_text)}</p></article>${renderWritingExtensions(c,feedback)}</section>`:`<section class="panel writing-desk"><header class="writing-desk-head"><div><span class="eyebrow">Votre production</span><h2>Rédigez votre réponse</h2></div><span id="draft-status">Brouillon local</span></header><label class="writing-editor" for="writing-text">Votre texte</label><textarea id="writing-text" rows="18" lang="fr" spellcheck="true" placeholder="Commencez par présenter le problème, puis développez votre proposition…"></textarea><div class="word-progress"><div><span id="word-count">0 mot</span><strong id="word-guidance">Commencez votre brouillon</strong></div><progress id="writing-word-progress" max="${c.max_words}" value="0" aria-label="Progression vers l’objectif de mots"></progress><div class="word-scale"><span>0</span><span>${c.min_words} min.</span><span>${c.max_words} max.</span></div></div><div class="writing-submit"><span>Votre brouillon reste sur cet appareil. Une seule correction finale est autorisée.</span><button id="submit-writing" class="primary" disabled>Envoyer pour correction</button></div></section>`}</div></div>`;bindCommon();if(!done)bindWritingEditor(task)}
function writingWordCount(text){return (text.match(/[A-Za-zÀ-ÿ]+(?:['’-][A-Za-zÀ-ÿ]+)*/g)||[]).length}
function bindWritingEditor(task){const c=task.content,textarea=document.querySelector('#writing-text'),counter=document.querySelector('#word-count'),guidance=document.querySelector('#word-guidance'),progress=document.querySelector('#writing-word-progress'),button=document.querySelector('#submit-writing'),draftStatus=document.querySelector('#draft-status'),desk=document.querySelector('.writing-desk'),draftKey=`french-writing-draft-${task.id}`;try{textarea.value=localStorage.getItem(draftKey)||task.draft_text||'';if(textarea.value)draftStatus.textContent=task.correction_error?'Texte restauré après l’échec de la correction':'Brouillon restauré'}catch(error){textarea.value=task.draft_text||'';draftStatus.textContent='Sauvegarde locale indisponible'}const update=(save=true)=>{const count=writingWordCount(textarea.value),remaining=c.min_words-count,over=count-c.max_words;counter.textContent=`${count} mot${count===1?'':'s'}`;progress.value=Math.min(count,c.max_words);desk.classList.toggle('word-target',count>=c.min_words&&count<=c.max_words);desk.classList.toggle('word-over',count>c.max_words);if(count===0)guidance.textContent='Commencez votre brouillon';else if(count<40){const needed=40-count;guidance.textContent=`Encore ${needed} mot${needed===1?'':'s'} avant de pouvoir demander une correction`}else if(count<c.min_words)guidance.textContent=`Continuez : ${remaining} mots avant l’objectif conseillé`;else if(count<=c.max_words)guidance.textContent='Objectif atteint · vous pouvez relire et envoyer';else guidance.textContent=`${over} mot${over===1?'':'s'} au-dessus de la longueur conseillée`;button.disabled=count<40;if(save)try{if(textarea.value.trim()){localStorage.setItem(draftKey,textarea.value);draftStatus.textContent='Brouillon sauvegardé sur cet appareil'}else{localStorage.removeItem(draftKey);draftStatus.textContent='Brouillon local'}}catch(error){draftStatus.textContent='Sauvegarde locale indisponible'}};textarea.addEventListener('input',update);button.addEventListener('click',()=>submitWriting(task.id));update(false)}
async function submitWriting(id){const text=document.querySelector('#writing-text').value.trim(),count=writingWordCount(text);if(count<40)return setStatus('Écrivez au moins 40 mots avant de demander la correction.',true);if(!confirm('Envoyer ce texte pour correction ? Il sera enregistré avant le début de l’analyse.'))return;const button=document.querySelector('#submit-writing');button.disabled=true;button.textContent='Enregistrement…';setStatus('Enregistrement de votre production…');try{const result=await api(`/api/writing/${id}/submit`,{method:'POST',body:JSON.stringify({text})});if(state.view==='writing'){renderWriting(result);setStatus(result.status==='completed'?'Correction terminée.':'Texte enregistré. Vous pouvez quitter cette page : la correction continue.')}}catch(e){if(state.view==='writing'){button.disabled=false;button.textContent='Envoyer pour correction';setStatus(e.message,true)}}}

function formatShortDate(value){return new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(`${value}T12:00:00Z`))}
function formatDate(value){return new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${value}T12:00:00Z`))}
function bindCommon(){view.querySelectorAll('[data-speak]').forEach(button=>button.addEventListener('click',()=>speak(button.dataset.speak,button)));view.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.view)))}
function navigate(name){stopSpeech();if(name!=='writing')clearWritingPoll();state.view=name;let active=null;document.querySelectorAll('.nav-item').forEach(item=>{const selected=item.dataset.view===name;item.classList.toggle('active',selected);if(selected)active=item});if(active&&window.innerWidth<=760)active.scrollIntoView({block:'nearest',inline:'center'});({today:showToday,history:showHistory,review:showReview,vocabulary:showVocabulary,reading:showReading,writing:showWriting}[name]||showToday)()}
document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.view)));
showToday();
